#include <Arduino.h>

void setup();
void loop();
void display(char c);
void setup() {
  pinMode(A0, OUTPUT);  
  pinMode(A1, OUTPUT);  
  pinMode(A2, OUTPUT);  
}
void loop() {
  display(0); 
  delay(2000); 
  display('A'); 
  delay(2000); 
  display('P'); 
  delay(2000); 
}
void display(char c) {
  byte data = 0;
  switch(c) {
    case 0:
      data = 0b1000000; 
      break;
    case 'A':
      data = 0b0001000; 
      break;
    case 'P':
      data = 0b0001100; 
      break;
  }
  shiftOut(A0, A2, MSBFIRST, data);  
  digitalWrite(A1, HIGH);  
  delayMicroseconds(1);
  digitalWrite(A1, LOW);
  delayMicroseconds(1);
}
